        debug_assert!(raw_cap > 0);

        Ok(HeaderMap {
            mask: (raw_cap - 1) as Size,
            indices: vec![Pos::none(); raw_cap].into_boxed_slice(),
            entries: Vec::with_capacity(usable_capacity(raw_cap)),
            extra_values: Vec::new(),
            danger: Danger::Green,
        })
    }
}

